const raw = $input.item.json.content || $input.item.json.message?.content || $input.item.json.response || '';
const cash = $('Build Ollama Prompt').item.json.cash || 0;

let parsed;
try {
  parsed = JSON.parse(raw.replace(/```json/g,'').replace(/```/g,'').trim());
} catch(e) {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) { parsed = JSON.parse(match[0]); }
  else { throw new Error('Could not parse Ollama response: ' + raw.substring(0,200)); }
}

const trades = parsed.trades || [];
const summary = parsed.summary || 'AI trade decision';
const hasDipTrades = trades.some(t => t.isDip);
return [{json: {trades, summary, cash, tradeCount: trades.length, hasDipTrades}}];

