const ticker = $json.ticker;
const amount = $json.amount;
const reason = $json.reason;
const isDip = $json.isDip || false;

// Known UK-listed ETFs on T212 (London Stock Exchange, append .L)
const ukEtfs = [
  'VUSA', 'VUAG', 'ISF', 'SWLD', 'VFEM', 'VERX', 'EQQQ',
  'VWRL', 'VHYL', 'VAPX', 'VJPN', 'VEUR', 'VUKE', 'VMID',
  'CSPX', 'IGUS', 'IUSA', 'IEEM', 'IWRD', 'IUKD', 'IUIT',
  'CSP1', 'SPXS', 'HMWO', 'HSBC', 'LTAM', 'LWDB', 'SMT',
  'DAGB', 'INRG', 'RBTX', 'BRIC', 'LGGG', 'AAPL', 'AMZN'
];

let yahooSymbol;

if (ticker.includes('_US_EQ')) {
  // Explicit US stock - strip suffix only
  yahooSymbol = ticker.replace('_US_EQ', '');
} else {
  // Strip the T212 suffix (lowercase letters + _EQ)
  const base = ticker.replace(/[a-z]*_EQ$/, '');

  // Check if it's a known UK-listed ETF
  const isUkListed = ukEtfs.some(etf => base.toUpperCase() === etf.toUpperCase());

  if (isUkListed) {
    yahooSymbol = base + '.L';
  } else {
    // Unknown ticker - try without .L first (US format)
    // Ollama sometimes hallucinates US tickers in UK format
    yahooSymbol = base;
  }
}

return [{json: {ticker, amount, reason, isDip, yahooSymbol, base: ticker.replace(/[a-z]*_EQ$/, '').replace('_US_EQ', '')}}];

const data = $input.item.json;
const ticker = $('Map Ticker to Yahoo').item.json.ticker;
const amount = $('Map Ticker to Yahoo').item.json.amount;
const reason = $('Map Ticker to Yahoo').item.json.reason;
const isDip = $('Map Ticker to Yahoo').item.json.isDip;

const result = data.chart?.result?.[0];
const price = result?.meta?.regularMarketPrice || result?.meta?.previousClose;

if (!price || price <= 0) {
  throw new Error('Could not get price for ' + ticker + ' (Yahoo: ' + $('Map Ticker to Yahoo').item.json.yahooSymbol + ')');
}

const quantity = Math.floor((amount / price) * 100) / 100;

const finalQty = Math.max(quantity, 0.01);
return [{json: {ticker, amount, reason, isDip, price, quantity: finalQty}}];

